CREATE TABLE "pedido_conta" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "pedido_conta_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"vinculo" varchar(12) NOT NULL,
	"nome" varchar(160) NOT NULL,
	"email" varchar(160) NOT NULL,
	"email_normalizado" varchar(160) NOT NULL,
	"organizacao" varchar(160) NOT NULL,
	"matricula" varchar(30),
	"situacao" varchar(12) DEFAULT 'PENDENTE' NOT NULL,
	"motivo" text,
	"decidido_por" integer,
	"decidido_em" timestamp with time zone,
	"usuario_id" integer,
	"ip" text,
	"criado_em" timestamp with time zone NOT NULL,
	CONSTRAINT "ck_pedido_conta_vinculo" CHECK (vinculo IN ('TERCEIRIZADO','DISCENTE')),
	CONSTRAINT "ck_pedido_conta_situacao" CHECK (situacao IN ('PENDENTE','APROVADO','RECUSADO','DESCARTADO'))
);
